-- Expanded public Cat Parts Store reference index, captured from category landing pages.
-- These are search-only references; no stock, price, or engine fitment is inferred.
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,technical_group=excluded.technical_group,
 source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',image_url=coalesce(excluded.image_url,public.part_catalog.image_url),
 specifications=excluded.specifications,updated_at=now();
